const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define region between Elkhorn and Platte Rivers near Omaha
  const omaha = ee.Geometry.Point([-95.94, 41.26]);
  const roi = ee.Geometry.Buffer(omaha, 15000); // 15km buffer

  // Function to mask clouds in Sentinel-2
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NDWI
  function calcNDWI(image) {
    const ndwi = image.normalizedDifference(['B8', 'B11']).rename('NDWI');
    return ndwi;
  }

  // Get March 2018 Sentinel-2 images
  const col2018 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(roi)
    .filterDate('2018-03-01', '2018-03-31')
    .map(maskClouds);

  const size2018 = col2018.size().getInfo();
  print('March 2018 Images: ' + size2018);

  if (size2018 === 0) {
    print('No images found for March 2018.');
    print('C1');
    return;
  }

  // Get March 16, 2019 Sentinel-2 image
  const col2019 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(roi)
    .filterDate('2019-03-16', '2019-03-17')
    .map(maskClouds);

  const size2019 = col2019.size().getInfo();
  print('March 16, 2019 Images: ' + size2019);

  if (size2019 === 0) {
    print('No images found for March 16, 2019.');
    print('C1');
    return;
  }

  // Calculate median NDWI for March 2018
  const ndwi2018 = col2018.map(calcNDWI).median();
  const water2018 = ndwi2018.gt(0.3);

  const count2018 = water2018.reduceRegion(
    {reducer: ee.Reducer.sum(), geometry: roi, scale: 30, maxPixels: 1e9}
  ).get('NDWI').getInfo();

  print('March 2018 Water Pixels: ' + Math.round(count2018 || 0));

  // Calculate NDWI for March 16, 2019
  const ndwi2019 = col2019.map(calcNDWI).median();
  const water2019 = ndwi2019.gt(0.3);

  const count2019 = water2019.reduceRegion(
    {reducer: ee.Reducer.sum(), geometry: roi, scale: 30, maxPixels: 1e9}
  ).get('NDWI').getInfo();

  print('March 2019 Water Pixels: ' + Math.round(count2019 || 0));

  // Validation checks
  if (count2018 === null || count2018 === undefined) {
    print('Invalid result for 2018.');
    print('C3');
    return;
  }

  if (count2019 === null || count2019 === undefined) {
    print('Invalid result for 2019.');
    print('C3');
    return;
  }

  if (count2018 === 0 && count2019 === 0) {
    print('No valid water pixels detected in either period.');
    print('C2');
    return;
  }

  // Compare extents
  const increase = count2019 - count2018;
  print('Water extent change: ' + Math.round(increase) + ' pixels');

  if (count2019 > count2018) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
